import csv
tsid = 'cb0edc8a-8eba-5a9c-89e5-fb3668b1fc18'
vals = {}
for r in csv.DictReader(open(VALUES_CSV)):
    if r['timeseries_id'] == tsid:
        vals[r['timestamp']] = float(r['value'])

def mean_on(date):
    sel = [v for t,v in vals.items() if t.startswith(date)]
    return sum(sel)/len(sel), len(sel)

m1,n1 = mean_on('2018-04-22')
m2,n2 = mean_on('2018-10-03')
print(m1,n1,m2,n2, m2-m1)
